#!/usr/bin/python3
"""Independent guest mlockall, future-map and munlockall qualification."""
import ctypes,json,mmap,os,resource,sys,uuid
from pathlib import Path
H=Path('/tmp/parity-home');C=Path('/tmp/parity-case')
if os.getuid()!=2000 or os.geteuid()!=2000 or Path.cwd()!=C or os.environ.get('HOME')!=str(H): raise SystemExit(125)
if Path('/sys/class/dmi/id/sys_vendor').read_text().strip()!='QEMU': raise SystemExit(125)
try: uuid.UUID(Path('/etc/bashos-parity-vm').read_text().strip())
except (OSError,ValueError): raise SystemExit(125)
soft,hard=resource.getrlimit(resource.RLIMIT_MEMLOCK)
pre_limit={'soft':soft,'hard':hard}
if hard!=resource.RLIM_INFINITY and hard<64*1024*1024:
    (H/'mlock-positive-control.json').write_text(json.dumps({'error':'hard limit too low','effective_before':pre_limit})+'\n');raise SystemExit(125)
resource.setrlimit(resource.RLIMIT_MEMLOCK,(64*1024*1024,hard))
post_soft,post_hard=resource.getrlimit(resource.RLIMIT_MEMLOCK)
def locked():
    for line in Path('/proc/self/status').read_text().splitlines():
        if line.startswith('VmLck:'):return int(line.split()[1])
    raise RuntimeError('VmLck unavailable')
lib=ctypes.CDLL(None,use_errno=True);result={'pid':os.getpid(),'effective_before':pre_limit,'effective_after':{'soft':post_soft,'hard':post_hard},'proc_self_limits':Path('/proc/self/limits').read_text()}
try:
    result['before_kb']=locked();ctypes.set_errno(0);result['all_rc']=lib.mlockall(3);result['all_errno']=ctypes.get_errno();result['locked_kb']=locked()
    if result['all_rc']==0:
        m=mmap.mmap(-1,1024*1024);result['future_kb']=locked();m.close();result['unlock_rc']=lib.munlockall();result['after_kb']=locked()
    result['ok']=(post_soft==64*1024*1024 and post_hard==hard and result.get('all_rc')==0 and result.get('locked_kb',0)>0 and result.get('future_kb',0)>result['locked_kb'] and result.get('unlock_rc')==0 and result.get('after_kb')==0)
finally:
    (H/'mlock-positive-control.json').write_text(json.dumps(result,sort_keys=True)+'\n')
if not result.get('ok'): sys.exit(125)

